  1   import { CustomEditor, type ExtensionAPI, type ExtensionContext } from "/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/dist/index.js";
  2   import {
  3   	decodeKittyPrintable,
  4   	type AutocompleteItem,
  5   	type AutocompleteProvider,
  6   	type AutocompleteSuggestions,
  7   	type EditorComponent,
  8   } from "/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/node_modules/@earendil-works/pi-tui/dist/index.js";
  9   import { AGENT_OPTIONS, analyzeAgentEditorInput, type OptionCursorExpectation } from "./command-line.js";
 10   
 11   type EditorFactory = NonNullable<ReturnType<ExtensionContext["ui"]["getEditorComponent"]>>;
 12   type CompletionModel = { provider: string; id: string; name?: string };
 13   type AutocompleteRuntimeEditor = EditorComponent & {
 14   	forceFileAutocomplete?: (explicitTab?: boolean) => void;
 15   	getCursor?: () => { line: number; col: number };
 16   	isShowingAutocomplete?: () => boolean;
 17   	tryTriggerAutocomplete?: (explicitTab?: boolean) => void;
 18   };
 19   
 20   const DECORATED_EDITOR = Symbol.for("pi-user-agents:autocomplete-editor");
 21   const THINKING_LEVELS = ["off", "minimal", "low", "medium", "high", "xhigh", "max"] as const;
 22   
 23   type DecoratedEditor = AutocompleteRuntimeEditor & { [DECORATED_EDITOR]?: true };
 24   
 25   /** @example getOptionItems(analyzeAgentEditorInput("/agent --thi", 12) as OptionCursorExpectation)[0]?.label // "--thinking <level>" */
 26   export function getOptionItems(expectation: OptionCursorExpectation): AutocompleteItem[] {
 27   	return AGENT_OPTIONS.flatMap((option) => {
 28   		if (!option.autocomplete || expectation.usedSemanticIds.has(option.semanticId)) return [];
 29   		return option.names
 30   			.filter((name) => name.startsWith(expectation.fragment))
 31   			.map((name) => ({
 32   				value: name,
 33   				label: option.arity === "value" ? `${name} <${option.placeholder}>` : name,
 34   				description: option.description,
 35   			}));
 36   	});
 37   }
 38   
 39   export function createAgentAutocompleteProvider(current: AutocompleteProvider, getModels: () => readonly CompletionModel[] = () => []): AutocompleteProvider {
 40   	return {
 41   		async getSuggestions(lines, cursorLine, cursorCol, options): Promise<AutocompleteSuggestions | null> {
 42   			if (cursorLine !== 0) return current.getSuggestions(lines, cursorLine, cursorCol, options);
 43   			const expectation = analyzeAgentEditorInput(lines[0] ?? "", cursorCol);
 44   			if (expectation?.kind === "option") {
 45   				const items = getOptionItems(expectation);
 46   				return items.length === 0 ? null : { items, prefix: expectation.fragment };
 47   			}
 48   			if (expectation?.kind === "value" && expectation.option.completionDomain === "thinking") {
 49   				const items = THINKING_LEVELS
 50   					.filter((level) => level.startsWith(expectation.fragment))
 51   					.map((level) => ({ value: level, label: level }));
 52   				return items.length === 0 ? null : { items, prefix: expectation.fragment };
 53   			}
 54   			if (expectation?.kind === "value" && expectation.option.completionDomain === "model") {
 55   				const items = getModelItems(expectation.fragment, getModels());
 56   				return items.length === 0 ? null : { items, prefix: expectation.fragment };
 57   			}
 58   			return current.getSuggestions(lines, cursorLine, cursorCol, options);
 59   		},
 60   
 61   		applyCompletion(lines, cursorLine, cursorCol, item, prefix) {
 62   			if (cursorLine !== 0) return current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
 63   			const expectation = analyzeAgentEditorInput(lines[0] ?? "", cursorCol);
 64   			if (expectation?.kind === "option" && getOptionItems(expectation).some((candidate) => candidate.value === item.value)) {
 65   				const option = AGENT_OPTIONS.find((candidate) => candidate.names.includes(item.value));
 66   				if (option?.arity === "value" && (option.completionDomain === "path" || option.completionDomain === undefined)) {
 67   					return applyGuardedOptionEdit(lines, expectation.replacementStart, expectation.replacementEnd, item.value);
 68   				}
 69   				return applyCompletionEdit(lines, expectation.replacementStart, expectation.replacementEnd, item.value);
 70   			}
 71   			const thinkingValue = expectation?.kind === "value"
 72   				&& expectation.option.completionDomain === "thinking"
 73   				&& THINKING_LEVELS.some((level) => level === item.value);
 74   			if (thinkingValue && expectation.kind === "value") {
 75   				return applyCompletionEdit(lines, expectation.replacementStart, expectation.replacementEnd, item.value);
 76   			}
 77   			const modelValue = expectation?.kind === "value"
 78   				&& expectation.option.completionDomain === "model"
 79   				&& getModelItems(expectation.fragment, getModels()).some((model) => model.value === item.value);
 80   			if (modelValue && expectation.kind === "value") {
 81   				return applyCompletionEdit(lines, expectation.replacementStart, expectation.replacementEnd, item.value);
 82   			}
 83   			if (expectation?.kind === "value" && expectation.option.completionDomain === "path") {
 84   				const result = current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
 85   				if (item.label.endsWith("/")) return result;
 86   				const completedLine = result.lines[result.cursorLine] ?? "";
 87   				const cursorAfterSeparator = /\s/.test(completedLine[result.cursorCol] ?? "") ? result.cursorCol + 1 : result.cursorCol;
 88   				return { ...result, cursorCol: cursorAfterSeparator };
 89   			}
 90   			return current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
 91   		},
 92   
 93   		shouldTriggerFileCompletion(lines, cursorLine, cursorCol) {
 94   			return current.shouldTriggerFileCompletion?.(lines, cursorLine, cursorCol) ?? true;
 95   		},
 96   	};
 97   }
 98   
 99   export function registerAgentAutocomplete(pi: ExtensionAPI): void {
100   	let autocompleteEditorFactory: EditorFactory | undefined;
101   
102   	function installEditorBridge(ctx: ExtensionContext): void {
103   		if (ctx.mode !== "tui") return;
104   		const previousEditorFactory = ctx.ui.getEditorComponent();
105   		if (autocompleteEditorFactory && previousEditorFactory === autocompleteEditorFactory) return;
106   
107   		autocompleteEditorFactory = (tui, theme, keybindings) => {
108   			const editor = previousEditorFactory?.(tui, theme, keybindings) ?? new CustomEditor(tui, theme, keybindings);
109   			return decorateAutocompleteEditor(
110   				editor,
111   				(data) => keybindings.matches(data, "tui.input.tab") || keybindings.matches(data, "tui.select.confirm"),
112   			);
113   		};
114   		ctx.ui.setEditorComponent(autocompleteEditorFactory);
115   	}
116   
117   	pi.on("session_start", (_event, ctx) => {
118   		if (ctx.mode !== "tui") return;
119   		ctx.ui.addAutocompleteProvider((current) => {
120   			installEditorBridge(ctx);
121   			return createAgentAutocompleteProvider(current, () => ctx.modelRegistry.getAll());
122   		});
123   		installEditorBridge(ctx);
124   	});
125   }
126   
127   function getModelItems(fragment: string, models: readonly CompletionModel[]): AutocompleteItem[] {
128   	const query = fragment.toLowerCase();
129   	return models
130   		.filter((model) => `${model.provider}/${model.id} ${model.name ?? ""}`.toLowerCase().includes(query))
131   		.map((model) => {
132   			const reference = `${model.provider}/${model.id}`;
133   			return { value: reference, label: reference, description: model.name && model.name !== model.id ? model.name : undefined };
134   		});
135   }
136   
137   function applyCompletionEdit(lines: string[], replacementStart: number, replacementEnd: number, value: string): { lines: string[]; cursorLine: number; cursorCol: number } {
138   	const line = lines[0] ?? "";
139   	const before = line.slice(0, replacementStart);
140   	const after = line.slice(replacementEnd).replace(/^\s+/, "");
141   	const insertion = `${value} `;
142   	const nextLines = [...lines];
143   	nextLines[0] = `${before}${insertion}${after}`;
144   	return { lines: nextLines, cursorLine: 0, cursorCol: before.length + insertion.length };
145   }
146   
147   function applyGuardedOptionEdit(lines: string[], replacementStart: number, replacementEnd: number, optionName: string): { lines: string[]; cursorLine: number; cursorCol: number } {
148   	const line = lines[0] ?? "";
149   	const before = line.slice(0, replacementStart);
150   	const after = line.slice(replacementEnd).replace(/^\s+/, "");
151   	const insertion = `${optionName} \"\" `;
152   	const nextLines = [...lines];
153   	nextLines[0] = `${before}${insertion}${after}`;
154   	return { lines: nextLines, cursorLine: 0, cursorCol: before.length + optionName.length + 2 };
155   }
156   
157   function decorateAutocompleteEditor<T extends EditorComponent>(editor: T, isCompletionAcceptance: (data: string) => boolean): T {
158   	const runtimeEditor = editor as DecoratedEditor;
159   	if (runtimeEditor[DECORATED_EDITOR]) return editor;
160   	const handleInput = editor.handleInput.bind(editor);
161   	editor.handleInput = (data) => {
162   		const getCursor = runtimeEditor.getCursor;
163   		if (typeof getCursor !== "function") throw new Error("pi-user-agents autocomplete requires editor.getCursor()");
164   		const beforeCursor = getCursor.call(editor);
165   		const beforeExpectation = beforeCursor.line === 0 ? analyzeAgentEditorInput(editor.getText(), beforeCursor.col) : undefined;
166   		const wasShowingAutocomplete = runtimeEditor.isShowingAutocomplete?.call(editor) ?? false;
167   		const printableCharacter = decodeKittyPrintable(data) ?? (data.length === 1 && data.charCodeAt(0) >= 32 ? data : undefined);
168   		handleInput(data);
169   
170   		const cursor = getCursor.call(editor);
171   		if (cursor.line !== 0) return;
172   		const expectation = analyzeAgentEditorInput(editor.getText(), cursor.col);
173   		const typedOptionDash = printableCharacter === "-" && expectation?.kind === "option";
174   		const acceptedChainedOption = wasShowingAutocomplete
175   			&& isCompletionAcceptance(data)
176   			&& beforeExpectation?.kind === "option"
177   			&& expectation?.kind === "value"
178   			&& (expectation.option.completionDomain === "thinking"
179   				|| expectation.option.completionDomain === "model"
180   				|| expectation.option.completionDomain === "path");
181   		const acceptedPathDirectory = wasShowingAutocomplete
182   			&& isCompletionAcceptance(data)
183   			&& beforeExpectation?.kind === "value"
184   			&& beforeExpectation.option.completionDomain === "path"
185   			&& expectation?.kind === "value"
186   			&& expectation.option.completionDomain === "path";
187   		if (!typedOptionDash && !acceptedChainedOption && !acceptedPathDirectory) return;
188   
189   		const pathCompletion = acceptedPathDirectory || (acceptedChainedOption && expectation?.kind === "value" && expectation.option.completionDomain === "path");
190   		if (pathCompletion) {
191   			const forceFileAutocomplete = runtimeEditor.forceFileAutocomplete;
192   			if (typeof forceFileAutocomplete !== "function") throw new Error("pi-user-agents autocomplete requires editor.forceFileAutocomplete()");
193   			forceFileAutocomplete.call(editor, false);
194   			return;
195   		}
196   		const triggerAutocomplete = runtimeEditor.tryTriggerAutocomplete;
197   		if (typeof triggerAutocomplete !== "function") throw new Error("pi-user-agents autocomplete requires editor.tryTriggerAutocomplete()");
198   		triggerAutocomplete.call(editor, false);
199   	};
200   	runtimeEditor[DECORATED_EDITOR] = true;
201   	return editor;
202   }
203   
