export async function handleAgentCommand(
	pi: ExtensionAPI,
	runningAgents: Set<RunningAgent>,
	widget: UserAgentWidget,
	isShuttingDown: () => boolean,
	nextAgentNumber: () => number,
	command: AgentCommandName,
	args: string,
	invocation: string,
	ctx: ExtensionCommandContext,
): Promise<void> {
	try {
		await startUserAgent(pi, runningAgents, widget, isShuttingDown, nextAgentNumber, command, args, invocation, ctx);
	} catch (error) {
		reportCommandError(pi, command, args, ctx, errorMessage(error));
	}
}

async function startUserAgent(
	pi: ExtensionAPI,
	runningAgents: Set<RunningAgent>,
	widget: UserAgentWidget,
	isShuttingDown: () => boolean,
	nextAgentNumber: () => number,
	command: AgentCommandName,
	args: string,
	invocation: string,
	ctx: ExtensionCommandContext,
): Promise<void> {
	const parsed = parseAgentCommand(args, command);
	const forwarded = resolveForwardedOptions(parsed.forwardedArgs, ctx);
	const model = forwarded.model ?? ctx.model;
	if (!model) throw new Error("No current model is selected; pass -m MODELNAME");
	const thinkingLevel = forwarded.thinkingLevel ?? pi.getThinkingLevel();
	const inheritedMessages = parsed.isolate ? [] : buildInheritedMessages(ctx);
	const runningAgent = createRunningAgent(nextAgentNumber(), command, model, parsed, invocation);

	runningAgents.add(runningAgent);
	logSteering(runningAgent.id, "agent-created", { command, taskLength: parsed.task.length });
	if (ctx.hasUI) {
		widget.setUI(ctx.ui);
		for (const warning of parsed.warnings) ctx.ui.notify(warning, "warning");
		ctx.ui.notify(formatStartNotification(runningAgent), "info");
		widget.ensureTimer();
		widget.update();
	}

	runningAgent.finished = runUserAgent(parsed.task, model, thinkingLevel, forwarded, inheritedMessages, ctx, runningAgent, widget)
		.then(async (response) => {
			logSteering(runningAgent.id, "agent-prompt-resolved", { responseLength: response.length });
			runningAgent.status = "done-waiting-to-post";
			runningAgent.completedAt = Date.now();
			runningAgent.responseText = response;
			widget.addCompleted(runningAgent, true);

			const sent = postUserAgentResult(pi, isShuttingDown, runningAgent.notifyMainAgent, {
				customType: MESSAGE_TYPE,
				content: formatResultMessage(runningAgent, response),
				display: true,
				details: buildMessageDetails(runningAgent, true),
			});
			if (sent) runningAgent.status = "posted";
		})
		.catch(async (error) => {
			if (runningAgent.aborted) {
				logSteering(runningAgent.id, "agent-aborted");
				return;
			}
			const message = errorMessage(error);
			logSteering(runningAgent.id, "agent-error", { error: message });
			runningAgent.status = "error";
			runningAgent.completedAt = Date.now();
			runningAgent.error = message;
			widget.addCompleted(runningAgent, false);

			const sent = postUserAgentResult(pi, isShuttingDown, runningAgent.notifyMainAgent, {
				customType: MESSAGE_TYPE,
				content: formatErrorMessage(runningAgent, message),
				display: true,
				details: buildMessageDetails(runningAgent, false),
			});
			if (sent) runningAgent.status = "posted";
		})
		.finally(() => {
			logSteering(runningAgent.id, "agent-disposed", { status: runningAgent.status });
			runningAgent.session?.dispose();
			runningAgents.delete(runningAgent);
			widget.update();
		});
}

function createRunningAgent(sequenceNumber: number, command: AgentCommandName, model: Model, parsed: ParsedAgentCommand, invocation: string): RunningAgent {
	return {
		id: `user-${sequenceNumber.toString(36)}`,
		command,
		inheritedContext: !parsed.isolate,
		model: formatModel(model),
		modelLabel: formatModelLabel(model),
		task: parsed.task,
		invocation,
		notifyMainAgent: parsed.context,
		status: "starting",
		startedAt: Date.now(),
		activeTools: new Map(),
		toolUses: 0,
		turnCount: 0,
		responseText: "",
		inheritedMessageCount: 0,
		finished: Promise.resolve(),
	};
}

function postUserAgentResult(
	pi: ExtensionAPI,
	isShuttingDown: () => boolean,
	notifyMainAgent: boolean,
	message: {
		customType: string;
		content: string;
		display: boolean;
		details: AgentCommandDetails;
	},
): boolean {
	if (isShuttingDown()) return false;
	if (notifyMainAgent) {
		// Steers into a streaming turn, or triggers an immediate response when idle.
		pi.sendMessage(message, { triggerTurn: true });
	} else {
		// TUI-only session entry: renders in the transcript but never enters the main agent's context.
		pi.appendEntry(message.customType, { content: message.content, details: message.details });
	}
	return true;
}

/** Session inputs derived from forwarded pi CLI options, ready to hand to the child session. */
type ChildResourceLoaderOptions = {
	systemPrompt?: string;
	appendSystemPrompt?: string[];
	additionalExtensionPaths?: string[];
	additionalSkillPaths?: string[];
	additionalPromptTemplatePaths?: string[];
	additionalThemePaths?: string[];
	noExtensions?: boolean;
	noSkills?: boolean;
	noPromptTemplates?: boolean;
	noThemes?: boolean;
	noContextFiles?: boolean;
};

type ForwardedOptions = {
	model?: Model;
	thinkingLevel?: ThinkingLevel;
	tools?: string[];
	excludeTools?: string[];
	noTools?: "all" | "builtin";
	resourceLoaderOptions?: ChildResourceLoaderOptions;
};

/** Turn forwarded pi CLI tokens into child-session inputs via pi's own parser, so new pi options flow through unchanged. */
export function resolveForwardedOptions(forwardedArgs: string[], ctx: ExtensionCommandContext): ForwardedOptions {
	if (forwardedArgs.length === 0) return {};
	const parsed = parseArgs(forwardedArgs);
	const errors = parsed.diagnostics.filter((diagnostic) => diagnostic.type === "error");
	if (errors.length > 0) throw new Error(errors.map((diagnostic) => diagnostic.message).join("; "));

	const forwarded: ForwardedOptions = {};
	if (parsed.model) {
		const resolved = resolveCliModel({ cliProvider: parsed.provider, cliModel: parsed.model, cliThinking: parsed.thinking, modelRegistry: ctx.modelRegistry });
		if (resolved.error) throw new Error(resolved.error);
		forwarded.model = resolved.model;
		if (!parsed.thinking && resolved.thinkingLevel) forwarded.thinkingLevel = resolved.thinkingLevel;
	}
	if (parsed.thinking) forwarded.thinkingLevel = parsed.thinking;

	if (parsed.noTools) forwarded.noTools = "all";
	else if (parsed.noBuiltinTools) forwarded.noTools = "builtin";
	if (parsed.tools) forwarded.tools = parsed.tools;
	if (parsed.excludeTools) forwarded.excludeTools = parsed.excludeTools;

	const resourceLoaderOptions = buildChildResourceLoaderOptions(parsed, ctx.cwd);
	if (resourceLoaderOptions) forwarded.resourceLoaderOptions = resourceLoaderOptions;
	return forwarded;
}

function buildChildResourceLoaderOptions(parsed: Args, cwd: string): ChildResourceLoaderOptions | undefined {
	const options: ChildResourceLoaderOptions = {};
	if (parsed.systemPrompt !== undefined) options.systemPrompt = parsed.systemPrompt;
	if (parsed.appendSystemPrompt) options.appendSystemPrompt = parsed.appendSystemPrompt;
	if (parsed.extensions) options.additionalExtensionPaths = resolveResourcePaths(parsed.extensions, cwd);
	if (parsed.skills) options.additionalSkillPaths = resolveResourcePaths(parsed.skills, cwd);
	if (parsed.promptTemplates) options.additionalPromptTemplatePaths = resolveResourcePaths(parsed.promptTemplates, cwd);
	if (parsed.themes) options.additionalThemePaths = resolveResourcePaths(parsed.themes, cwd);
	if (parsed.noExtensions) options.noExtensions = true;
	if (parsed.noSkills) options.noSkills = true;
	if (parsed.noPromptTemplates) options.noPromptTemplates = true;
	if (parsed.noThemes) options.noThemes = true;
	if (parsed.noContextFiles) options.noContextFiles = true;
	return Object.keys(options).length > 0 ? options : undefined;
}

/** Resolve resource paths to absolute against the session cwd, matching how the CLI hands them to the loader. */
function resolveResourcePaths(values: string[], cwd: string): string[] {
	return values.map((value) => {
		if (value === "~" || value.startsWith("~/")) return path.join(os.homedir(), value.slice(1));
		return path.isAbsolute(value) ? value : path.resolve(cwd, value);
	});
}

function buildInheritedMessages(ctx: ExtensionCommandContext): AgentMessage[] {
	return structuredClone(buildSessionContext(ctx.sessionManager.getBranch()).messages);
}

async function runUserAgent(
	task: string,
	model: Model,
	thinkingLevel: ThinkingLevel,
	forwarded: ForwardedOptions,
	inheritedMessages: AgentMessage[],
	ctx: ExtensionCommandContext,
	runningAgent: RunningAgent,
	widget: UserAgentWidget,
): Promise<string> {
	const agentDir = getAgentDir();
	const settingsManager = SettingsManager.create(ctx.cwd, agentDir, { projectTrusted: ctx.isProjectTrusted() });
	const services = await createAgentSessionServices({
		cwd: ctx.cwd,
		agentDir,
		authStorage: ctx.modelRegistry.authStorage,
		modelRegistry: ctx.modelRegistry,
		settingsManager,
		resourceLoaderOptions: forwarded.resourceLoaderOptions,
	});
	const childModel = services.modelRegistry.find(model.provider, model.id) ?? model;
	const { session } = await createAgentSessionFromServices({
		services,
		sessionManager: SessionManager.inMemory(ctx.cwd),
		model: childModel,
		thinkingLevel,
		tools: forwarded.tools,
		excludeTools: forwarded.excludeTools,
		noTools: forwarded.noTools,
	});

	runningAgent.session = session;
	runningAgent.status = "running";
	logSteering(runningAgent.id, "session-created", { streaming: session.isStreaming });
	if (runningAgent.aborted) void session.abort();
	widget.update();

	await session.bindExtensions({ mode: "print" });
	logSteering(runningAgent.id, "session-bound", { streaming: session.isStreaming });
	if (inheritedMessages.length > 0) {
		session.agent.state.messages = inheritedMessages;
		runningAgent.inheritedMessageCount = inheritedMessages.length;
		logSteering(runningAgent.id, "context-inherited", { messageCount: inheritedMessages.length });
	}

	const unsubscribe = subscribeToChildSession(session, runningAgent, widget);
	try {
		logSteering(runningAgent.id, "initial-prompt-started", { streaming: session.isStreaming, taskLength: task.length });
		await session.prompt(task);
		logSteering(runningAgent.id, "initial-prompt-settled", { streaming: session.isStreaming, messageCount: session.agent.state.messages.length });
		return getFinalAssistantText(session);
	} finally {
		unsubscribe();
		logSteering(runningAgent.id, "session-shutdown", { streaming: session.isStreaming });
		await session.extensionRunner.emit({ type: "session_shutdown", reason: "quit" });
	}
}

function subscribeToChildSession(session: AgentSession, runningAgent: RunningAgent, widget: UserAgentWidget): () => void {
	return session.subscribe((event: AgentSessionEvent) => {
		if (event.type === "agent_start") logSteering(runningAgent.id, "child-agent-started", { streaming: session.isStreaming });
		if (event.type === "agent_end") logSteering(runningAgent.id, "child-agent-ended", { streaming: session.isStreaming, messageCount: event.messages.length });
		if (event.type === "agent_settled") logSteering(runningAgent.id, "child-agent-settled", { streaming: session.isStreaming });
		if (event.type === "turn_start") logSteering(runningAgent.id, "turn-started", { streaming: session.isStreaming });
		if (event.type === "turn_end") logSteering(runningAgent.id, "turn-ended", { streaming: session.isStreaming });
		if (event.type === "message_start") logSteering(runningAgent.id, "message-started", { role: event.message.role, streaming: session.isStreaming });
		const finalizedMessageUpdate = event.type === "message_update" && event.assistantMessageEvent.type.endsWith("_end");
		if (finalizedMessageUpdate || event.type === "message_end") runningAgent.latestFinalizedMessage = structuredClone(event.message);
		if (finalizedMessageUpdate && event.message.role === "assistant" && event.assistantMessageEvent.type === "text_end") {
			runningAgent.responseText = assistantText(event.message);
		}
		if (event.type === "message_end" && event.message.role === "assistant") runningAgent.responseText = assistantText(event.message);
		if (event.type === "tool_execution_start") {
			runningAgent.activeTools.set(event.toolCallId, event.toolName);
		}
		if (event.type === "tool_execution_end") {
			runningAgent.activeTools.delete(event.toolCallId);
			runningAgent.toolUses += 1;
		}
		if (event.type === "turn_end") {
			runningAgent.turnCount += 1;
		}
		if (event.type === "message_update" && !finalizedMessageUpdate) return;
		widget.update();
	});
}

function assistantText(message: Extract<AgentMessage, { role: "assistant" }>): string {
	return message.content
		.filter((part) => part.type === "text")
		.map((part) => part.text)
		.join("\n");
}

function getFinalAssistantText(session: AgentSession): string {
	const assistantMessages = session.agent.state.messages.filter((message) => message.role === "assistant");
	const lastMessage = assistantMessages.at(-1);
	if (!lastMessage) throw new Error("User agent finished without an assistant message");
	if (lastMessage.stopReason === "error" || lastMessage.stopReason === "aborted") {
		throw new Error(lastMessage.errorMessage ?? `User agent ${lastMessage.stopReason}`);
	}

	const text = assistantText(lastMessage).trim();
	if (!text) throw new Error("User agent returned no text response");
	return text;
}

