import assert from "node:assert/strict";
import { describe, test } from "bun:test";
import { parseAgentCommand } from "../runner.ts";

describe("model option aliases", () => {
	test("-m and --model produce the same semantic command", () => {
		const shortForm = parseAgentCommand("-m gpt56s explain it", "agent");
		const longForm = parseAgentCommand("--model gpt56s explain it", "agent");

		assert.deepEqual(
			shortForm,
			longForm,
			`Expected -m and --model to be exact aliases.\n-m: ${JSON.stringify(shortForm)}\n--model: ${JSON.stringify(longForm)}`,
		);
	});
});

import assert from "node:assert/strict";
import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, test } from "bun:test";
import { createEditorHarness } from "./editor-harness.ts";

describe("agent command editor autocomplete", () => {
	test("typing /agent - visibly opens the option menu without Tab", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent -");
		await harness.waitForAutocomplete();
		const rendered = harness.render();

		assert.match(rendered, /-m <model>/, `Expected the visible menu to contain -m <model>.\nRendered editor:\n${rendered}`);
		assert.match(rendered, /--model <model>/, `Expected the visible menu to contain --model <model>.\nRendered editor:\n${rendered}`);
	});

	test("/agent-isolated eagerly offers options but suppresses both isolation spellings", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent-isolated -");
		await harness.waitForAutocomplete();
		const rendered = harness.render();

		assert.match(rendered, /-m <model>/, `Expected /agent-isolated to open the option menu.\nRendered editor:\n${rendered}`);
		assert.doesNotMatch(rendered, /\n[→ ]+-i\s+Start without/, `Expected /agent-isolated to suppress -i.\nRendered editor:\n${rendered}`);
		assert.doesNotMatch(rendered, /\n[→ ]+--isolate\s+Start without/, `Expected /agent-isolated to suppress --isolate.\nRendered editor:\n${rendered}`);
	});

	test("accepting --thinking chains into its value menu and completes with one trailing space", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent --thi");
		await harness.waitForRender((rendered) => rendered.includes("--thinking <level>") && !rendered.includes("-m <model>"));
		harness.press("\t");
		assert.equal(harness.editor.getText(), "/agent --thinking ", `Expected the option edit before value chaining. Got: ${harness.editor.getText()}`);

		await harness.waitForAutocomplete();
		await harness.waitForRender((rendered) => rendered.includes("high"));
		harness.type("high");
		await harness.waitForRender((rendered) => rendered.includes("high") && !rendered.includes("off"));
		harness.press("\t");

		const expected = "/agent --thinking high ";
		assert.equal(harness.editor.getText(), expected, `Expected one trailing space after the thinking value. Got: ${harness.editor.getText()}`);
		assert.equal(harness.editor.getCursor().col, expected.length, `Expected the cursor after the trailing space. Got: ${harness.editor.getCursor().col}`);
	});

	test("a model option chains into the live model catalog and inserts its canonical reference", async () => {
		const harness = await createEditorHarness(process.cwd(), [
			{ provider: "openai-codex", id: "gpt-5.6-sol", name: "gpt56s" },
		]);

		harness.type("/agent -m");
		await harness.waitForRender((rendered) => rendered.includes("-m <model>") && !rendered.includes("--model <model>"));
		harness.press("\t");
		assert.equal(harness.editor.getText(), "/agent -m ", `Expected the model option edit before chaining. Got: ${harness.editor.getText()}`);

		await harness.waitForRender((rendered) => rendered.includes("openai-codex/gpt-5.6-sol"));
		harness.press("\t");
		const expected = "/agent -m openai-codex/gpt-5.6-sol ";
		assert.equal(harness.editor.getText(), expected, `Expected the canonical live model reference. Got: ${harness.editor.getText()}`);
		assert.equal(harness.editor.getCursor().col, expected.length, "Expected the model cursor after one trailing separator");
	});

	test("using either model alias suppresses both spellings from the next option menu", async () => {
		for (const modelOption of ["-m", "--model"]) {
			const harness = await createEditorHarness(process.cwd(), [{ provider: "openai-codex", id: "gpt-5.6-sol" }]);
			harness.type(`/agent ${modelOption}`);
			await harness.waitForRender((rendered) => rendered.includes(`${modelOption} <model>`));
			harness.press("\t");
			await harness.waitForRender((rendered) => rendered.includes("openai-codex/gpt-5.6-sol"));
			harness.press("\t");
			harness.type("-");
			await harness.waitForAutocomplete();

			const rendered = harness.render();
			assert.doesNotMatch(rendered, /-m <model>/, `Expected ${modelOption} to suppress -m.\nRendered editor:\n${rendered}`);
			assert.doesNotMatch(rendered, /--model <model>/, `Expected ${modelOption} to suppress --model.\nRendered editor:\n${rendered}`);
		}
	});

	test("--provider chains into the unique providers from the live model catalog", async () => {
		const harness = await createEditorHarness(process.cwd(), [
			{ provider: "openai-codex", id: "gpt-5.6-sol" },
			{ provider: "openai-codex", id: "gpt-5.5" },
			{ provider: "anthropic", id: "claude-opus-4-8" },
		]);

		harness.type("/agent --prov");
		await harness.waitForRender((rendered) => rendered.includes("--provider <provider>") && !rendered.includes("--prompt-template"));
		harness.press("\t");
		await harness.waitForRender((rendered) => rendered.includes("openai-codex") && rendered.includes("anthropic"));
		harness.type("openai");
		await harness.waitForRender((rendered) => rendered.includes("openai-codex") && !rendered.includes("anthropic"));
		harness.press("\t");

		const expected = "/agent --provider openai-codex ";
		assert.equal(harness.editor.getText(), expected, `Expected the selected live provider plus one separator. Got: ${harness.editor.getText()}`);
		assert.equal(harness.editor.getCursor().col, expected.length, "Expected the provider cursor after one trailing separator");
	});

	test("--provider scopes the live model menu for both model option spellings", async () => {
		const models = [
			{ provider: "openai-codex", id: "gpt-5.6-sol" },
			{ provider: "anthropic", id: "claude-opus-4-8" },
		];

		for (const modelOption of ["-m", "--model"]) {
			const harness = await createEditorHarness(process.cwd(), models);
			harness.type(`/agent --provider openai-codex ${modelOption}`);
			await harness.waitForRender((rendered) => rendered.includes(`${modelOption} <model>`));
			harness.press("\t");
			await harness.waitForRender((rendered) => rendered.includes("openai-codex/gpt-5.6-sol"));

			const rendered = harness.render();
			assert.doesNotMatch(
				rendered,
				/anthropic\/claude-opus-4-8/,
				`Expected --provider to scope the ${modelOption} live model menu.\nRendered editor:\n${rendered}`,
			);
		}
	});

	test("a free-form option creates a guarded quoted slot without a fake value menu", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent --sys");
		await harness.waitForRender((rendered) => rendered.includes("--system-prompt <text>") && !rendered.includes("--append-system-prompt"));
		harness.press("\t");

		assert.equal(harness.editor.getText(), '/agent --system-prompt "" ', `Expected a guarded free-form slot. Got: ${harness.editor.getText()}`);
		assert.equal(harness.editor.getCursor().col, '/agent --system-prompt "'.length, "Expected the cursor between the guarded quotes");
		assert.equal(harness.editor.isShowingAutocomplete(), false, "Expected no synthetic picker for a free-form value");

		harness.type("be terse");
		assert.equal(harness.editor.getText(), '/agent --system-prompt "be terse" ', "Expected typed text to remain inside the guarded quotes");
	});

	test("path completion traverses inside guarded quotes and finishes after the outer space", async () => {
		const cwd = await mkdtemp(join(tmpdir(), "pi-user-agents-autocomplete-"));
		try {
			await mkdir(join(cwd, "assets"));
			await writeFile(join(cwd, "assets", "child.txt"), "fixture");
			const harness = await createEditorHarness(cwd);

			harness.type("/agent --ski");
			await harness.waitForRender((rendered) => rendered.includes("--skill <path>") && !rendered.includes("-m <model>"));
			harness.press("\t");
			assert.equal(harness.editor.getText(), '/agent --skill "" ', `Expected a guarded path slot. Got: ${harness.editor.getText()}`);
			assert.equal(harness.editor.getCursor().col, '/agent --skill "'.length, "Expected the cursor inside the guarded path slot");

			await harness.waitForRender((rendered) => rendered.includes("assets/"));
			harness.press("\t");
			assert.equal(harness.editor.getText(), '/agent --skill "assets/" ', `Expected directory traversal to preserve the guarded slot. Got: ${harness.editor.getText()}`);
			assert.equal(harness.editor.getCursor().col, '/agent --skill "assets/'.length, "Expected the directory cursor before the closing quote");

			await harness.waitForRender((rendered) => rendered.includes("child.txt"));
			harness.press("\t");
			const expected = '/agent --skill "assets/child.txt" ';
			assert.equal(harness.editor.getText(), expected, `Expected the completed quoted path plus one separator. Got: ${harness.editor.getText()}`);
			assert.equal(harness.editor.getCursor().col, expected.length, "Expected the completed-file cursor after the outer separator");
		} finally {
			await rm(cwd, { recursive: true, force: true });
		}
	});
});

import { CustomEditor, type ExtensionAPI, type ExtensionContext } from "/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/dist/index.js";
import {
	decodeKittyPrintable,
