const QUOTE_PAIRS: Readonly<Record<string, string>> = { '"': '"', "'": "'", "`": "`", "‘": "’", "“": "”" };

function valueOptionsWithoutChildEffect(): AgentOptionDefinition[] {
	return [
		legacyValueOption("api-key", ["--api-key"]),
