function blockedOption(semanticId: string, names: readonly string[]): AgentOptionDefinition {
	return { semanticId, names, role: "blocked", arity: "boolean", autocomplete: false, description: "Unsupported for background runs" };
}

/**
 * Parse submitted agent-command arguments through the shared option declaration.
 *
 * @example parseAgentCommand("-m gpt56s explain it", "agent").forwardedArgs // ["--model", "gpt56s"]
 */
export function parseAgentCommand(args: string, command: AgentCommandName): ParsedAgentCommand {
	let isolate = false;
	let context = false;
	const forwardedArgs: string[] = [];
	let rest = args;
	let consumedOption = false;

	for (;;) {
		const trimmed = rest.replace(/^\s+/, "");
		const token = /^\S+/.exec(trimmed)?.[0];
		const option = token === undefined ? undefined : OPTION_BY_NAME.get(token);
		if (token === undefined || option === undefined) {
			rest = consumedOption ? trimmed : args;
			break;
		}
		if (option.role === "blocked") {
			throw new Error(`/${command} does not support ${token}; it would disrupt the background agent run.`);
		}

		const remainder = trimmed.slice(token.length);
		if (option.semanticId === "isolate") {
			isolate = true;
			rest = remainder;
		} else if (option.semanticId === "context") {
			context = true;
			rest = remainder;
		} else if (option.arity === "value") {
			forwardedArgs.push(option.forwardName ?? token);
			const read = readOptionValue(remainder);
			if (read.value !== undefined) forwardedArgs.push(read.value);
			rest = read.rest;
		} else {
			forwardedArgs.push(option.forwardName ?? token);
			rest = remainder;
		}
		consumedOption = true;
	}

	const prose = rest;
	if (!prose.trim()) throw new Error(`Usage: /${command} [pi options] [-m MODELNAME] [-i|--isolate] [-c|--context] "<task>"`);
	const quoteMask = buildQuoteMask(prose);
	return {
		isolate,
		context,
		forwardedArgs,
		task: unescapeProse(prose, quoteMask),
		warnings: collectProseWarnings(prose, quoteMask, command),
	};
}

/**
 * Analyze the cursor in a complete editor line without committing a partial token as prose.
 *
 * @example analyzeAgentEditorInput("/agent --thi", 12)?.kind // "option"
 */
export function analyzeAgentEditorInput(line: string, cursor: number): AgentCursorExpectation | undefined {
	const commandMatch = /^\/(agent-isolated|agent)(?=$|\s)/.exec(line);
	if (!commandMatch || cursor <= commandMatch[0].length || cursor > line.length) return undefined;
	const command = commandMatch[1] as AgentCommandName;
	const argumentOffset = commandMatch[0].length;
	const expectation = analyzeArgumentCursor(line.slice(argumentOffset), cursor - argumentOffset, command);
	if (!expectation) return undefined;
	return {
		...expectation,
		replacementStart: expectation.replacementStart + argumentOffset,
		replacementEnd: expectation.replacementEnd + argumentOffset,
	};
}

function analyzeArgumentCursor(args: string, cursor: number, command: AgentCommandName): AgentCursorExpectation | undefined {
	const usedSemanticIds = new Set<string>(command === "agent-isolated" ? ["isolate"] : []);
	let position = 0;
	let expectedValueOption: AgentOptionDefinition | undefined;
	let provider: string | undefined;

	for (;;) {
		while (position < args.length && /\s/.test(args[position] ?? "")) position += 1;
		if (position >= cursor) {
			if (expectedValueOption) {
				return valueExpectation(command, "", cursor, cursor, expectedValueOption, provider, false, usedSemanticIds);
			}
			return optionExpectation(command, "", cursor, cursor, usedSemanticIds);
		}

		if (expectedValueOption) {
			const value = readCursorValue(args, position);
			if (cursor <= value.end) {
				const fragmentStart = value.quoted ? value.start + 1 : value.start;
				const fragmentEnd = value.quoted ? Math.max(fragmentStart, value.end - 1) : value.end;
				return valueExpectation(
					command,
					args.slice(fragmentStart, cursor),
					fragmentStart,
					fragmentEnd,
					expectedValueOption,
					provider,
					value.quoted,
					usedSemanticIds,
				);
			}
			if (expectedValueOption.semanticId === "provider") {
				provider = args.slice(value.quoted ? value.start + 1 : value.start, value.quoted ? value.end - 1 : value.end);
			}
			position = value.end;
			expectedValueOption = undefined;
			continue;
		}

		const tokenStart = position;
		while (position < args.length && !/\s/.test(args[position] ?? "")) position += 1;
		const tokenEnd = position;
		if (cursor <= tokenEnd) {
			const fragment = args.slice(tokenStart, cursor);
			if (!fragment.startsWith("-")) return undefined;
			return optionExpectation(command, fragment, tokenStart, tokenEnd, usedSemanticIds);
		}

		const token = args.slice(tokenStart, tokenEnd);
		const option = OPTION_BY_NAME.get(token);
		if (!option || option.role === "blocked") return undefined;
		usedSemanticIds.add(option.semanticId);
		if (option.arity === "value") expectedValueOption = option;
	}
}

function optionExpectation(
	command: AgentCommandName,
	fragment: string,
	replacementStart: number,
	replacementEnd: number,
	usedSemanticIds: ReadonlySet<string>,
): OptionCursorExpectation {
	return { kind: "option", command, fragment, replacementStart, replacementEnd, usedSemanticIds };
}

function valueExpectation(
	command: AgentCommandName,
	fragment: string,
	replacementStart: number,
	replacementEnd: number,
	option: AgentOptionDefinition,
	parsedProvider: string | undefined,
	quoted: boolean,
	usedSemanticIds: ReadonlySet<string>,
): ValueCursorExpectation {
	return { kind: "value", command, fragment, option, parsedProvider, replacementStart, replacementEnd, quoted, usedSemanticIds };
}

function readCursorValue(args: string, start: number): { start: number; end: number; quoted: boolean } {
	const closer = QUOTE_PAIRS[args[start] ?? ""];
	if (closer !== undefined) {
		const close = args.indexOf(closer, start + 1);
		if (close !== -1) return { start, end: close + 1, quoted: true };
	}
	let end = start;
	while (end < args.length && !/\s/.test(args[end] ?? "")) end += 1;
	return { start, end, quoted: false };
}

function readOptionValue(rest: string): { value: string | undefined; rest: string } {
	const afterOption = rest.replace(/^\s+/, "");
	const closer = QUOTE_PAIRS[afterOption[0] ?? ""];
	if (closer !== undefined) {
		const close = afterOption.indexOf(closer, 1);
		if (close !== -1) return { value: afterOption.slice(1, close), rest: afterOption.slice(close + 1) };
	}
	const token = /^\S+/.exec(afterOption)?.[0];
	return token === undefined ? { value: undefined, rest: afterOption } : { value: token, rest: afterOption.slice(token.length) };
}

function buildQuoteMask(text: string): boolean[] {
	const mask = new Array<boolean>(text.length).fill(false);
	let index = 0;
	while (index < text.length) {
		const closer = QUOTE_PAIRS[text[index] ?? ""];
		const close = closer === undefined ? -1 : text.indexOf(closer, index + 1);
		if (close === -1) {
			index += 1;
			continue;
		}
		for (let position = index; position <= close; position += 1) mask[position] = true;
		index = close + 1;
	}
	return mask;
}

function collectProseWarnings(prose: string, quoteMask: boolean[], command: AgentCommandName): string[] {
	const tokens: { text: string; index: number }[] = [];
	const pattern = /\S+/g;
	for (let match = pattern.exec(prose); match !== null; match = pattern.exec(prose)) {
		tokens.push({ text: match[0], index: match.index });
	}
	const firstToken = tokens[0];
	const firstProseWord = quoteMask[firstToken.index] ? firstToken.text : unescapeWord(firstToken.text);
	const warnings: string[] = [];
	for (let index = 0; index < tokens.length; index += 1) {
		const token = tokens[index];
		if (quoteMask[token.index]) continue;
		const option = OPTION_BY_NAME.get(token.text);
		if (!option) continue;
		const value = option.arity === "value" ? tokens[index + 1]?.text : undefined;
		const optionWithValue = value === undefined ? token.text : `${token.text} ${value}`;
		warnings.push(
			`${optionWithValue} was included in the prompt body. To specify an argument or an option, place it at the beginning of the command input: /${command} ${optionWithValue} ${firstProseWord} …`,
		);
	}
	return warnings;
}

function unescapeWord(word: string): string {
	if (!word.startsWith("\\-")) return word;
	const unescaped = word.slice(1);
	return unescaped.startsWith("-\\-") ? `-${unescaped.slice(2)}` : unescaped;
}

function unescapeProse(prose: string, quoteMask: boolean[]): string {
	return prose.replace(/\S+/g, (word, offset: number) => (quoteMask[offset] ? word : unescapeWord(word)));
}

