test("/agent-isolated eagerly offers options but suppresses both isolation spellings", async () => {
	const harness = await createEditorHarness();

	harness.type("/agent-isolated -");
	await harness.waitForAutocomplete();
	const rendered = harness.render();

	assert.match(rendered, /-m <model>/, `Expected /agent-isolated to open the option menu.\nRendered editor:\n${rendered}`);
	assert.doesNotMatch(rendered, /\n[→ ]+-i\s+Start without/, `Expected /agent-isolated to suppress -i.\nRendered editor:\n${rendered}`);
	assert.doesNotMatch(rendered, /\n[→ ]+--isolate\s+Start without/, `Expected /agent-isolated to suppress --isolate.\nRendered editor:\n${rendered}`);
});

test("task prose, quoted dashes, and escaped dashes never reopen option autocomplete", async () => {
	for (const text of ["/agent explain -", '/agent "-"', "/agent \\-"]) {
		const harness = await createEditorHarness();
		harness.type(text);
		await harness.waitForAutocompleteToRemainHidden();

		assert.equal(harness.editor.isShowingAutocomplete(), false, `Expected no option menu for ${JSON.stringify(text)}.`);
	}
});

test("blocked options remain absent while an effective option with the same prefix is visible", async () => {
	const harness = await createEditorHarness();

	harness.type("/agent --ex");
	await harness.waitForRender((rendered) => rendered.includes("--exclude-tools <tools>"));
	const rendered = harness.render();

	assert.doesNotMatch(rendered, /--export/, `Expected blocked --export to remain absent.\nRendered editor:\n${rendered}`);
});

test("mid-line completion replaces only the active fragment and preserves the task suffix", async () => {
	const harness = await createEditorHarness();
	const suffix = " explain it";

	harness.type(`/agent --thi${suffix}`);
	harness.moveCursorLeft(suffix.length);
	harness.press("\t");
	assert.equal(harness.editor.getText(), "/agent --thinking explain it", "Expected Tab to replace the active option fragment");
	await harness.waitForRender((rendered) => rendered.includes("off"));
	harness.press("\t");

	const expected = "/agent --thinking off explain it";
	assert.equal(harness.editor.getText(), expected, `Expected mid-line completion to preserve the suffix. Got: ${harness.editor.getText()}`);
	assert.equal(harness.editor.getCursor().col, "/agent --thinking off ".length, "Expected the cursor before the preserved suffix");
});

