			}
			if (expectation?.kind === "value" && expectation.option.completionDomain === "thinking") {
				const items = THINKING_LEVELS.filter((level) => level.startsWith(expectation.fragment)).map(
					(level) => ({ value: level, label: level }),
				);
				return items.length === 0 ? null : { items, prefix: expectation.fragment };
			}
			if (expectation?.kind === "value" && expectation.option.completionDomain === "model") {
				const items = getModelItems(expectation.fragment, getModels(), expectation.parsedProvider);
				return items.length === 0 ? null : { items, prefix: expectation.fragment };
			}
			if (expectation?.kind === "value" && expectation.option.completionDomain === "provider") {
				const items = getProviderItems(expectation.fragment, getModels());
				return items.length === 0 ? null : { items, prefix: expectation.fragment };
			}
			return current.getSuggestions(lines, cursorLine, cursorCol, options);
		},

		applyCompletion(lines, cursorLine, cursorCol, item, prefix) {
			if (cursorLine !== 0)
				return current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
			const expectation = analyzeAgentEditorInput(lines[0] ?? "", cursorCol);
			if (
				expectation?.kind === "option" &&
				getOptionItems(expectation).some((candidate) => candidate.value === item.value)
			) {
				const option = AGENT_OPTIONS.find((candidate) => candidate.names.includes(item.value));
				if (
					option?.arity === "value" &&
					(option.completionDomain === "path" || option.completionDomain === undefined)
				) {
					return applyGuardedOptionEdit(
						lines,
						expectation.replacementStart,
						expectation.replacementEnd,
						item.value,
					);
				}
				return applyCompletionEdit(
					lines,
					expectation.replacementStart,
					expectation.replacementEnd,
					item.value,
				);
			}
			const thinkingValue =
				expectation?.kind === "value" &&
				expectation.option.completionDomain === "thinking" &&
				THINKING_LEVELS.some((level) => level === item.value);
			if (thinkingValue && expectation.kind === "value") {
				return applyCompletionEdit(
					lines,
					expectation.replacementStart,
					expectation.replacementEnd,
					item.value,
				);
			}
			const modelValue =
				expectation?.kind === "value" &&
				expectation.option.completionDomain === "model" &&
				getModelItems(expectation.fragment, getModels(), expectation.parsedProvider).some(
					(model) => model.value === item.value,
				);
			if (modelValue && expectation.kind === "value") {
				return applyCompletionEdit(
					lines,
					expectation.replacementStart,
					expectation.replacementEnd,
					item.value,
				);
			}
			const providerValue =
				expectation?.kind === "value" &&
				expectation.option.completionDomain === "provider" &&
				getProviderItems(expectation.fragment, getModels()).some(
					(provider) => provider.value === item.value,
				);
			if (providerValue && expectation.kind === "value") {
				return applyCompletionEdit(
					lines,
					expectation.replacementStart,
					expectation.replacementEnd,
					item.value,
				);
			}
			if (expectation?.kind === "value" && expectation.option.completionDomain === "path") {
				const result = current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
				if (item.label.endsWith("/")) return result;
				const completedLine = result.lines[result.cursorLine] ?? "";
				const cursorAfterSeparator = /\s/.test(completedLine[result.cursorCol] ?? "")
					? result.cursorCol + 1
					: result.cursorCol;
				return { ...result, cursorCol: cursorAfterSeparator };
			}
			return current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
		},

		shouldTriggerFileCompletion(lines, cursorLine, cursorCol) {
			return current.shouldTriggerFileCompletion?.(lines, cursorLine, cursorCol) ?? true;
		},
	};
}

export function registerAgentAutocomplete(pi: ExtensionAPI): void {
	let autocompleteEditorFactory: EditorFactory | undefined;

	function installEditorBridge(ctx: ExtensionContext): void {
		if (ctx.mode !== "tui") return;
		const previousEditorFactory = ctx.ui.getEditorComponent();
		if (autocompleteEditorFactory && previousEditorFactory === autocompleteEditorFactory) return;

		autocompleteEditorFactory = (tui, theme, keybindings) => {
			const editor =
				previousEditorFactory?.(tui, theme, keybindings) ??
				new CustomEditor(tui, theme, keybindings);
			return decorateAutocompleteEditor(
				editor,
				(data) =>
					keybindings.matches(data, "tui.input.tab") ||
					keybindings.matches(data, "tui.select.confirm"),
			);
		};
		ctx.ui.setEditorComponent(autocompleteEditorFactory);
	}

	pi.on("session_start", (_event, ctx) => {
		if (ctx.mode !== "tui") return;
		ctx.ui.addAutocompleteProvider((current) => {
			installEditorBridge(ctx);
			return createAgentAutocompleteProvider(current, () => ctx.modelRegistry.getAll());
		});
		installEditorBridge(ctx);
	});
}

function getModelItems(
	fragment: string,
	models: readonly CompletionModel[],
	provider?: string,
): AutocompleteItem[] {
	const query = fragment.toLowerCase();
	return models
		.filter((model) => provider === undefined || model.provider === provider)
		.filter((model) =>
			`${model.provider}/${model.id} ${model.name ?? ""}`.toLowerCase().includes(query),
		)
		.map((model) => {
			const reference = `${model.provider}/${model.id}`;
			return {
				value: reference,
				label: reference,
				description: model.name && model.name !== model.id ? model.name : undefined,
			};
		});
}

function getProviderItems(
	fragment: string,
	models: readonly CompletionModel[],
): AutocompleteItem[] {
	const query = fragment.toLowerCase();
	return [...new Set(models.map((model) => model.provider))]
		.filter((provider) => provider.toLowerCase().includes(query))
		.map((provider) => ({ value: provider, label: provider }));
}

function applyCompletionEdit(
	lines: string[],
	replacementStart: number,
	replacementEnd: number,
	value: string,
): { lines: string[]; cursorLine: number; cursorCol: number } {
	const line = lines[0] ?? "";
	const before = line.slice(0, replacementStart);
	const after = line.slice(replacementEnd).replace(/^\s+/, "");
	const insertion = `${value} `;
	const nextLines = [...lines];
	nextLines[0] = `${before}${insertion}${after}`;
	return { lines: nextLines, cursorLine: 0, cursorCol: before.length + insertion.length };
}

function applyGuardedOptionEdit(
	lines: string[],
	replacementStart: number,
	replacementEnd: number,
	optionName: string,
): { lines: string[]; cursorLine: number; cursorCol: number } {
	const line = lines[0] ?? "";
	const before = line.slice(0, replacementStart);
	const after = line.slice(replacementEnd).replace(/^\s+/, "");
	const insertion = `${optionName} "" `;
	const nextLines = [...lines];
	nextLines[0] = `${before}${insertion}${after}`;
	return { lines: nextLines, cursorLine: 0, cursorCol: before.length + optionName.length + 2 };
}

function decorateAutocompleteEditor<T extends EditorComponent>(
	editor: T,
	isCompletionAcceptance: (data: string) => boolean,
): T {
	const runtimeEditor = editor as DecoratedEditor;
	if (runtimeEditor[DECORATED_EDITOR]) return editor;
	const handleInput = editor.handleInput.bind(editor);
	editor.handleInput = (data) => {
		const getCursor = runtimeEditor.getCursor;
		if (typeof getCursor !== "function")
			throw new Error("pi-user-agents autocomplete requires editor.getCursor()");
		const beforeCursor = getCursor.call(editor);
		const beforeExpectation =
			beforeCursor.line === 0
				? analyzeAgentEditorInput(editor.getText(), beforeCursor.col)
				: undefined;
		const wasShowingAutocomplete = runtimeEditor.isShowingAutocomplete?.call(editor) ?? false;
		const printableCharacter =
			decodeKittyPrintable(data) ??
			(data.length === 1 && data.charCodeAt(0) >= 32 ? data : undefined);
		handleInput(data);

		const cursor = getCursor.call(editor);
		if (cursor.line !== 0) return;
		const expectation = analyzeAgentEditorInput(editor.getText(), cursor.col);
		const typedOptionDash = printableCharacter === "-" && expectation?.kind === "option";
		const completionAcceptance = isCompletionAcceptance(data);
		const acceptedChainedOption =
			wasShowingAutocomplete &&
			completionAcceptance &&
			beforeExpectation?.kind === "option" &&
			expectation?.kind === "value" &&
			expectation.option.completionDomain !== undefined;
		const acceptedPathDirectory =
			wasShowingAutocomplete &&
			completionAcceptance &&
			beforeExpectation?.kind === "value" &&
			beforeExpectation.option.completionDomain === "path" &&
			expectation?.kind === "value" &&
			expectation.option.completionDomain === "path";
		const optionItems =
			beforeExpectation?.kind === "option" ? getOptionItems(beforeExpectation) : [];
		const onlyOption =
			optionItems.length === 1
				? AGENT_OPTIONS.find((option) => option.names.includes(optionItems[0]?.value ?? ""))
				: undefined;
		const pendingChainedOption =
			!wasShowingAutocomplete &&
			completionAcceptance &&
			expectation?.kind === "option" &&
			onlyOption?.completionDomain !== undefined;
		if (pendingChainedOption) {
			observeChainedOptionEdit(editor, runtimeEditor, onlyOption.semanticId);
			return;
		}
		if (!typedOptionDash && !acceptedChainedOption && !acceptedPathDirectory) return;

		if (acceptedPathDirectory) {
			triggerValueAutocomplete(editor, runtimeEditor, expectation);
			return;
		}
		if (acceptedChainedOption) {
			triggerValueAutocomplete(editor, runtimeEditor, expectation);
			return;
		}
		const triggerAutocomplete = runtimeEditor.tryTriggerAutocomplete;
		if (typeof triggerAutocomplete !== "function")
			throw new Error("pi-user-agents autocomplete requires editor.tryTriggerAutocomplete()");
		triggerAutocomplete.call(editor, false);
	};
	runtimeEditor[DECORATED_EDITOR] = true;
	return editor;
}

function observeChainedOptionEdit(
	editor: EditorComponent,
	runtimeEditor: AutocompleteRuntimeEditor,
	semanticId: string,
): void {
	const deadline = Date.now() + 500;
	const observe = (): void => {
		const cursor = runtimeEditor.getCursor?.call(editor);
		const expectation =
			cursor?.line === 0 ? analyzeAgentEditorInput(editor.getText(), cursor.col) : undefined;
		if (
			expectation?.kind === "value" &&
			expectation.option.semanticId === semanticId &&
			expectation.option.completionDomain !== undefined
		) {
			triggerValueAutocomplete(editor, runtimeEditor, expectation);
			return;
		}
		if (runtimeEditor.isShowingAutocomplete?.call(editor) || Date.now() >= deadline) return;
		setTimeout(observe, 5);
	};
	setTimeout(observe, 0);
}

function triggerValueAutocomplete(
	editor: EditorComponent,
	runtimeEditor: AutocompleteRuntimeEditor,
	expectation: ValueCursorExpectation,
): void {
	if (expectation.option.completionDomain === "path") {
		const forceFileAutocomplete = runtimeEditor.forceFileAutocomplete;
		if (typeof forceFileAutocomplete !== "function")
			throw new Error("pi-user-agents autocomplete requires editor.forceFileAutocomplete()");
		forceFileAutocomplete.call(editor, false);
		return;
	}
	const triggerAutocomplete = runtimeEditor.tryTriggerAutocomplete;
	if (typeof triggerAutocomplete !== "function")
		throw new Error("pi-user-agents autocomplete requires editor.tryTriggerAutocomplete()");
	triggerAutocomplete.call(editor, false);
}

import { describe, test } from "bun:test";
import assert from "node:assert/strict";
import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createEditorHarness } from "./editor-harness.ts";

describe("agent command editor autocomplete", () => {
	test("typing /agent - visibly opens the option menu without Tab", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent -");
		await harness.waitForAutocomplete();
		const rendered = harness.render();

		assert.match(
			rendered,
			/-m <model>/,
			`Expected the visible menu to contain -m <model>.\nRendered editor:\n${rendered}`,
		);
		assert.match(
			rendered,
			/--model <model>/,
			`Expected the visible menu to contain --model <model>.\nRendered editor:\n${rendered}`,
		);
	});

	test("rapid repeated dash triggers settle on the current non-empty option menu", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent -");
		for (let attempt = 0; attempt < 10; attempt += 1) {
			harness.press("\x7f");
			harness.type("-");
		}
		await harness.waitForAutocomplete();
		const rendered = harness.render();

		assert.equal(
			harness.editor.getText(),
			"/agent -",
			`Expected rapid edits to retain the current input. Got: ${harness.editor.getText()}`,
		);
		assert.match(
			rendered,
			/-m <model>/,
			`Expected the settled menu to contain model completion.\nRendered editor:\n${rendered}`,
		);
	});

	test("/agent-isolated eagerly offers options but suppresses both isolation spellings", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent-isolated -");
		await harness.waitForAutocomplete();
		const rendered = harness.render();

		assert.match(
			rendered,
			/-m <model>/,
			`Expected /agent-isolated to open the option menu.\nRendered editor:\n${rendered}`,
		);
		assert.doesNotMatch(
			rendered,
			/\n[→ ]+-i\s+Start without/,
			`Expected /agent-isolated to suppress -i.\nRendered editor:\n${rendered}`,
		);
		assert.doesNotMatch(
			rendered,
			/\n[→ ]+--isolate\s+Start without/,
			`Expected /agent-isolated to suppress --isolate.\nRendered editor:\n${rendered}`,
		);
	});

	test("task prose, quoted dashes, and escaped dashes never reopen option autocomplete", async () => {
		for (const text of ["/agent explain -", '/agent "-"', "/agent \\-"]) {
			const harness = await createEditorHarness();
			harness.type(text);
			await harness.waitForAutocompleteToRemainHidden();

			assert.equal(
				harness.editor.isShowingAutocomplete(),
				false,
				`Expected no option menu for ${JSON.stringify(text)}.`,
			);
		}
	});

	test("blocked options remain absent while an effective option with the same prefix is visible", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent --ex");
		await harness.waitForRender((rendered) => rendered.includes("--exclude-tools <tools>"));
		const rendered = harness.render();

		assert.doesNotMatch(
			rendered,
			/--export/,
			`Expected blocked --export to remain absent.\nRendered editor:\n${rendered}`,
		);
	});

	test("mid-line completion replaces only the active fragment and preserves the task suffix", async () => {
		const harness = await createEditorHarness();
		const suffix = " explain it";

		harness.type(`/agent --thi${suffix}`);
		harness.moveCursorLeft(suffix.length);
		harness.press("\t");
		await harness.waitForRender((rendered) => rendered.includes("/agent --thinking explain it"));
		assert.equal(
			harness.editor.getText(),
			"/agent --thinking explain it",
			"Expected Tab to replace the active option fragment",
		);
		await harness.waitForRender((rendered) => rendered.includes("off"));
		harness.press("\t");

		const expected = "/agent --thinking off explain it";
		assert.equal(
			harness.editor.getText(),
			expected,
			`Expected mid-line completion to preserve the suffix. Got: ${harness.editor.getText()}`,
		);
		assert.equal(
			harness.editor.getCursor().col,
			"/agent --thinking off ".length,
			"Expected the cursor before the preserved suffix",
		);
	});

	test("accepting --thinking chains into its value menu and completes with one trailing space", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent --thi");
		await harness.waitForRender(
			(rendered) => rendered.includes("--thinking <level>") && !rendered.includes("-m <model>"),
		);
		harness.press("\t");
		assert.equal(
			harness.editor.getText(),
			"/agent --thinking ",
			`Expected the option edit before value chaining. Got: ${harness.editor.getText()}`,
		);

		await harness.waitForAutocomplete();
		await harness.waitForRender((rendered) => rendered.includes("high"));
		harness.type("high");
		await harness.waitForRender(
			(rendered) => rendered.includes("high") && !rendered.includes("off"),
		);
		harness.press("\t");

		const expected = "/agent --thinking high ";
		assert.equal(
			harness.editor.getText(),
			expected,
			`Expected one trailing space after the thinking value. Got: ${harness.editor.getText()}`,
		);
		assert.equal(
			harness.editor.getCursor().col,
			expected.length,
			`Expected the cursor after the trailing space. Got: ${harness.editor.getCursor().col}`,
		);
	});

	test("Enter accepts an enumerable option and value without submitting the command", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent --thi");
		await harness.waitForRender((rendered) => rendered.includes("--thinking <level>"));
		harness.press("\r");
		await harness.waitForRender((rendered) => rendered.includes("off"));
		harness.press("\r");

		const expected = "/agent --thinking off ";
		assert.equal(
			harness.editor.getText(),
			expected,
			`Expected Enter to accept without submitting. Got: ${harness.editor.getText()}`,
		);
		assert.equal(
			harness.editor.getCursor().col,
			expected.length,
			"Expected the cursor after the trailing separator",
		);
		assert.equal(
			harness.editor.isShowingAutocomplete(),
			false,
			"Expected the value menu to close after acceptance",
		);
	});

	test("a model option chains into the live model catalog and inserts its canonical reference", async () => {
		const harness = await createEditorHarness(process.cwd(), [
			{ provider: "openai-codex", id: "gpt-5.6-sol", name: "gpt56s" },
		]);

		harness.type("/agent -m");
		await harness.waitForRender(
			(rendered) => rendered.includes("-m <model>") && !rendered.includes("--model <model>"),
		);
		harness.press("\t");
		assert.equal(
			harness.editor.getText(),
			"/agent -m ",
			`Expected the model option edit before chaining. Got: ${harness.editor.getText()}`,
		);

		await harness.waitForRender((rendered) => rendered.includes("openai-codex/gpt-5.6-sol"));
		harness.press("\t");
		const expected = "/agent -m openai-codex/gpt-5.6-sol ";
		assert.equal(
			harness.editor.getText(),
			expected,
			`Expected the canonical live model reference. Got: ${harness.editor.getText()}`,
		);
		assert.equal(
			harness.editor.getCursor().col,
			expected.length,
			"Expected the model cursor after one trailing separator",
		);
	});

	test("using either model alias suppresses both spellings from the next option menu", async () => {
		for (const modelOption of ["-m", "--model"]) {
			const harness = await createEditorHarness(process.cwd(), [
				{ provider: "openai-codex", id: "gpt-5.6-sol" },
			]);
			harness.type(`/agent ${modelOption}`);
			await harness.waitForRender((rendered) => rendered.includes(`${modelOption} <model>`));
			harness.press("\t");
			await harness.waitForRender((rendered) => rendered.includes("openai-codex/gpt-5.6-sol"));
			harness.press("\t");
			harness.type("-");
			await harness.waitForAutocomplete();

			const rendered = harness.render();
			assert.doesNotMatch(
				rendered,
				/-m <model>/,
				`Expected ${modelOption} to suppress -m.\nRendered editor:\n${rendered}`,
			);
			assert.doesNotMatch(
				rendered,
				/--model <model>/,
				`Expected ${modelOption} to suppress --model.\nRendered editor:\n${rendered}`,
			);
		}
	});

	test("--provider chains into the unique providers from the live model catalog", async () => {
		const harness = await createEditorHarness(process.cwd(), [
			{ provider: "openai-codex", id: "gpt-5.6-sol" },
			{ provider: "openai-codex", id: "gpt-5.5" },
			{ provider: "anthropic", id: "claude-opus-4-8" },
		]);

		harness.type("/agent --prov");
		await harness.waitForRender(
			(rendered) =>
				rendered.includes("--provider <provider>") && !rendered.includes("--prompt-template"),
		);
		harness.press("\t");
		await harness.waitForRender(
			(rendered) => rendered.includes("openai-codex") && rendered.includes("anthropic"),
		);
		harness.type("openai");
		await harness.waitForRender(
			(rendered) => rendered.includes("openai-codex") && !rendered.includes("anthropic"),
		);
		harness.press("\t");

		const expected = "/agent --provider openai-codex ";
		assert.equal(
			harness.editor.getText(),
			expected,
			`Expected the selected live provider plus one separator. Got: ${harness.editor.getText()}`,
		);
		assert.equal(
			harness.editor.getCursor().col,
			expected.length,
			"Expected the provider cursor after one trailing separator",
		);
	});

	test("--provider scopes the live model menu for both model option spellings", async () => {
		const models = [
			{ provider: "openai-codex", id: "gpt-5.6-sol" },
			{ provider: "anthropic", id: "claude-opus-4-8" },
		];

		for (const modelOption of ["-m", "--model"]) {
			const harness = await createEditorHarness(process.cwd(), models);
			harness.type(`/agent --provider openai-codex ${modelOption}`);
			await harness.waitForRender((rendered) => rendered.includes(`${modelOption} <model>`));
			harness.press("\t");
			await harness.waitForRender((rendered) => rendered.includes("openai-codex/gpt-5.6-sol"));

			const rendered = harness.render();
			assert.doesNotMatch(
				rendered,
				/anthropic\/claude-opus-4-8/,
				`Expected --provider to scope the ${modelOption} live model menu.\nRendered editor:\n${rendered}`,
			);
		}
	});

	test("a free-form option creates a guarded quoted slot without a fake value menu", async () => {
		const harness = await createEditorHarness();

		harness.type("/agent --sys");
		await harness.waitForRender(
			(rendered) =>
				rendered.includes("--system-prompt <text>") && !rendered.includes("--append-system-prompt"),
		);
		harness.press("\t");

		assert.equal(
			harness.editor.getText(),
			'/agent --system-prompt "" ',
			`Expected a guarded free-form slot. Got: ${harness.editor.getText()}`,
		);
		assert.equal(
			harness.editor.getCursor().col,
			'/agent --system-prompt "'.length,
			"Expected the cursor between the guarded quotes",
		);
		assert.equal(
			harness.editor.isShowingAutocomplete(),
			false,
			"Expected no synthetic picker for a free-form value",
		);

		harness.type("be terse");
		assert.equal(
			harness.editor.getText(),
			'/agent --system-prompt "be terse" ',
			"Expected typed text to remain inside the guarded quotes",
		);
	});

	test("path completion traverses inside guarded quotes and finishes after the outer space", async () => {
		const cwd = await mkdtemp(join(tmpdir(), "pi-user-agents-autocomplete-"));
		try {
			await mkdir(join(cwd, "assets"));
			await writeFile(join(cwd, "assets", "child.txt"), "fixture");
			const harness = await createEditorHarness(cwd);

			harness.type("/agent --ski");
			await harness.waitForRender(
				(rendered) => rendered.includes("--skill <path>") && !rendered.includes("-m <model>"),
			);
			harness.press("\t");
			assert.equal(
				harness.editor.getText(),
				'/agent --skill "" ',
				`Expected a guarded path slot. Got: ${harness.editor.getText()}`,
			);
			assert.equal(
				harness.editor.getCursor().col,
				'/agent --skill "'.length,
				"Expected the cursor inside the guarded path slot",
			);

			await harness.waitForRender((rendered) => rendered.includes("assets/"));
			harness.press("\t");
			assert.equal(
				harness.editor.getText(),
				'/agent --skill "assets/" ',
				`Expected directory traversal to preserve the guarded slot. Got: ${harness.editor.getText()}`,
			);
			assert.equal(
				harness.editor.getCursor().col,
				'/agent --skill "assets/'.length,
				"Expected the directory cursor before the closing quote",
